      '<div class="card"><div class="card-head"><h2>Visitas por día</h2></div><div class="bars">' + views.map((v, i) => '<div class="b" title="' + days[i] + ': ' + v + '"><div class="pair"><i class="exp" style="height:' + Math.round(v / max * 100) + '%;width:70%;max-width:18px"></i></div>' + (i % 5 === 0 ? '<span class="lbl">' + days[i].slice(8) + '/' + days[i].slice(5, 7) + '</span>' : '<span class="lbl">&nbsp;</span>') + '</div>').join('') + '</div></div>' +
      '<div class="grid g2" style="margin-top:16px"><div class="card"><h2>Productos más vistos</h2>' + (prods.length ? prods.map(([k, n]) => '<div class="hbar"><span class="name">' + esc(k) + '</span><span class="track"><i style="width:' + Math.round(n / pmax * 100) + '%"></i></span><span class="val">' + n + '</span></div>').join('') : empty('Sin datos todavía.')) + '</div><div class="card"><h2>Páginas más visitadas</h2>' + (pages.length ? pages.map(([k, n]) => '<div class="sum-line"><span>' + esc(k) + '</span><b>' + n + '</b></div>').join('') : empty('Sin datos todavía.')) + '</div></div>' +
      '<div class="card" style="margin-top:16px"><div class="card-head"><h2>Interesados</h2><p>Personas que empezaron una compra o financiación en la página</p></div><div class="list">' + (peds.length ? peds.map((p) => { const c = A.db.clients[p.phone]; return '<div class="item"><div class="grow"><div class="main-t">' + esc(p.prod || 'Consulta') + '</div><div class="sub-t">' + esc((c ? c.name + ' · ' : '') + (p.phone || '') + ' · ' + (p.f || '') + (p.plan ? ' · ' + p.plan : '') + (p.adel ? ' · adelanto ' + p.adel : '')) + '</div><div class="row-flex" style="margin-top:6px;gap:6px">' + ['nueva', 'respondida', 'vendida', 'perdida'].map((e) => '<button class="btn-sm ' + ((p.estado || 'nueva') === e ? '' : 'btn-2') + '" data-act="ped-state" data-id="' + esc(p.id) + '" data-v="' + e + '">' + e.charAt(0).toUpperCase() + e.slice(1) + '</button>').join('') + '</div></div><div class="row-flex">' + (p.phone ? '<a class="btn btn-sm btn-wa" target="_blank" rel="noopener" href="' + A.waLink(p.phone, 'Hola' + (c ? ' ' + A.first(c.name) : '') + ', te escribimos de ICLUB por tu consulta sobre ' + (p.prod || 'el equipo') + '.') + '">WhatsApp</a>' : '') + '<button class="btn-sm btn-brand" data-act="ped-sell" data-id="' + esc(p.id) + '">Pasar a venta</button></div></div>'; }).join('') : empty('No hay interesados todavía.')) + '</div></div>';
